                name: item.name || uuid,
                enrolledAt: item.enrolledAt || null,
                source: item.source || 'manual'
            };
        })
    }
};
flow.set('fleetSnapshot', snapshot);
msg.topic = 'fleet_snapshot';
msg.payload = snapshot;
if (msg._uibOrigin) msg._uib = { originator: msg._uibOrigin };
return msg;

const cfg = flow.get('fleetAdminConfig') || {};
const appIds = String(cfg.balenaAppIds || env.get('BALENA_APP_IDS') || cfg.balenaAppId || env.get('BALENA_APP_ID') || '').trim();
const snapshot = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (snapshot.admin && snapshot.admin.balena) {
    snapshot.admin.balena.appIds = appIds;
    snapshot.admin.balena.appId = appIds;
    snapshot.admin.balena.configured = !!snapshot.admin.balena.tokenSet && !!appIds;
    snapshot.admin.balena.source = cfg.balenaToken || cfg.balenaAppIds || cfg.balenaAppId ? 'ui' : (env.get('BALENA_API_TOKEN') || env.get('BALENA_APP_IDS') || env.get('BALENA_APP_ID') ? 'env' : 'none');
}
msg.payload = snapshot;
flow.set('fleetSnapshot', snapshot);
return msg;

const code = Number(msg.statusCode || 0) || 0;
const retryCount = Number(msg.teamsRetryCount || 0);
const maxRetries = 2;
const request = msg.teamsRequest || null;
const snapshot = { topic: 'fleet_state_changed' };

if (code >= 200 && code < 300) {
    flow.set('fleetTeamsLastError', null);
    flow.set('fleetTeamsLastSuccessAt', Date.now());
    node.status({ fill: 'green', shape: 'dot', text: 'Teams HTTP ' + code });
    return [snapshot, null];
}

const retryable = code === 429 || code >= 500 || code === 0 || !!msg.error;
if (retryable && retryCount < maxRetries && request && request.url) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'Teams retry ' + (retryCount + 1) + '/' + maxRetries });
    return [null, {
        method: request.method || 'POST',
        url: request.url,
        headers: request.headers || { 'Content-Type': 'application/json' },
        payload: request.payload,
        teamsRequest: request,
        teamsRetryCount: retryCount + 1
    }];
}

const errText = (msg.error && (msg.error.message || String(msg.error)))
    || ('HTTP ' + (code || 'inconnu'));
flow.set('fleetTeamsLastError', {
    source: 'teams',
    at: Date.now(),
    message: errText,
    statusCode: code || null,
    retries: retryCount
});
node.warn('Watchdog fleet Teams webhook error: ' + errText);
node.status({ fill: 'yellow', shape: 'ring', text: 'Teams ' + errText });
return [snapshot, null];

const cfg = flow.get('fleetAdminConfig') || {};
const webhook = String(cfg.teamsWebhookUrl || env.get('TEAMS_WEBHOOK_URL') || '').trim();
if (!webhook) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'TEAMS_WEBHOOK_URL vide' });
    node.warn('TEAMS_WEBHOOK_URL est requis pour la galerie Teams');
    return null;
}

function parisTime() {
    return new Date().toLocaleString('fr-CH', { timeZone: 'Europe/Paris' });
}

function card(title, color, state, detail) {
    return {
        method: 'POST',
        url: webhook,
        headers: { 'Content-Type': 'application/json' },
        payload: {
            type: 'message',
            attachments: [{
                contentType: 'application/vnd.microsoft.teams.card.adaptive',
                contentUrl: null,
                content: {
                    $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
                    type: 'AdaptiveCard',
                    version: '1.4',
                    body: [
                        { type: 'TextBlock', size: 'Large', weight: 'Bolder', text: title, wrap: true, color: color },
                        { type: 'TextBlock', text: 'Carte de simulation — aucune alarme réelle', wrap: true, isSubtle: true },
                        { type: 'FactSet', facts: [
                            { title: 'Source', value: 'HUB de supervision' },
                            { title: 'Appareil', value: 'Gateway Démo' },
                            { title: 'État', value: state },
                            { title: 'Détail', value: detail },
                            { title: 'Quand', value: parisTime() }
                        ] }
                    ]
                }
            }]
        }
    };
}

node.status({ fill: 'blue', shape: 'dot', text: '4 simulations en file' });
return [[
    card('[SIMULATION] Avertissement — HUB Watchdog Hub', 'warning', 'Cloud Balena indisponible', 'Heartbeat MQTT reçu : la collecte locale peut continuer.'),
    card('[SIMULATION] Alerte haute — HUB Watchdog Hub', 'attention', 'Heartbeat absent', 'Balena est joignable mais le watchdog applicatif ne répond plus.'),
    card('[SIMULATION] Critique — HUB Watchdog Hub', 'attention', 'Gateway hors service', 'Balena offline et heartbeat MQTT absent depuis plus de 5 minutes.'),
    card('[SIMULATION] Retour à la normale — HUB Watchdog Hub', 'good', 'Opérationnel', 'Balena et heartbeat MQTT sont de nouveau disponibles.')
]];

if (!msg.teamsRequest) {
    msg.teamsRequest = {
        method: msg.method || 'POST',
        url: msg.url,
        headers: msg.headers,
        payload: msg.payload
    };
}
if (!Number.isFinite(Number(msg.teamsRetryCount))) msg.teamsRetryCount = 0;
return msg;
